mapper.select:
select gym_id as gymId, item_category as itemCategory, item_name as itemName, sum(item_count) as itemCount from "h_item" where gym_id=#{gymId}
and (item_name like concat('%', #{pager.searchKeyword}, '%') or item_category like concat('%', #{pager.searchKeyword}, '%'))
group by gym_id, item_category, item_name order by item_name limit #{pager.pageSize} offset #{pager.offset}

select count(*) from ( select 1 from "h_item" where gym_id=#{gymId}
and (item_name like concat('%', #{pager.searchKeyword}, '%') or item_category like concat('%', #{pager.searchKeyword}, '%'))
group by gym_id, item_category, item_name ) t

select * from "h_item"
where gym_id = #{gymId} and item_name = #{itemName}
order by item_date desc
